const colors = {
    reset: '\x1b[0m',
    bold: '\x1b[1m',
    dim: '\x1b[2m',
    green: '\x1b[32m',
    yellow: '\x1b[33m',
    red: '\x1b[31m',
    cyan: '\x1b[36m',
    magenta: '\x1b[35m',
};
export const log = {
    info: (message) => console.log(`${colors.cyan}${colors.bold}  ●  ${colors.reset}${message}`),
    success: (message) => console.log(`${colors.green}${colors.bold}  ✔  ${colors.reset}${message}`),
    warn: (message) => console.log(`${colors.yellow}${colors.bold}  ⚠  ${colors.reset}${message}`),
    error: (message) => console.error(`${colors.red}${colors.bold}  ✖  ${colors.reset}${message}`),
    step: (message) => console.log(`${colors.magenta}${colors.bold}  ->  ${colors.reset}${message}`),
    dim: (message) => console.log(`${colors.dim}     ${message}${colors.reset}`),
    blank: () => console.log(),
    banner: () => {
        console.log();
        console.log(`${colors.cyan}${colors.bold}  ██╗    ██╗███████╗██████╗  █████╗ ██████╗ ██╗  ██╗██╗███████╗██╗   ██╗`);
        console.log(`${colors.cyan}${colors.bold}  ██║    ██║██╔════╝██╔══██╗██╔══██╗██╔══██╗██║ ██╔╝██║██╔════╝╚██╗ ██╔╝`);
        console.log(`${colors.cyan}${colors.bold}  ██║ █╗ ██║█████╗  ██████╔╝███████║██████╔╝█████╔╝ ██║█████╗   ╚████╔╝ `);
        console.log(`${colors.cyan}${colors.bold}  ██║███╗██║██╔══╝  ██╔══██╗██╔══██║██╔═══╝ ██╔═██╗ ██║██╔══╝    ╚██╔╝  `);
        console.log(`${colors.cyan}${colors.bold}  ╚███╔███╔╝███████╗██████╔╝██║  ██║██║     ██║  ██╗██║██║        ██║   `);
        console.log(`${colors.cyan}${colors.bold}   ╚══╝╚══╝ ╚══════╝╚═════╝ ╚═╝  ╚═╝╚═╝     ╚═╝  ╚═╝╚═╝╚═╝        ╚═╝   `);
        console.log(`${colors.reset}${colors.dim}  Wrap any web app as a native Android APK${colors.reset}`);
        console.log();
    },
};
